SELECT payment_type, COUNT(*) AS payment_count
FROM order_payments
GROUP BY payment_type;

SELECT COUNT(*) AS products_without_category
FROM products
WHERE product_category_name IS NULL;

SELECT COUNT(*) AS total_orders_2017
FROM orders
WHERE strftime('%Y', order_purchase_timestamp) = '2017';

SELECT COUNT(DISTINCT customer_id) AS unique_customers_in_curitiba
FROM customers
WHERE customer_city = 'Curitiba';

SELECT AVG(payment_installments) AS avg_installments
FROM order_payments
WHERE payment_type = 'credit card';

SELECT payment_type, AVG(payment_value) AS avg_payment_value
FROM order_payments
GROUP BY payment_type;
